import {analyze,sarif,compare,RULES} from './analyzer.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let report=null,baseline=null,filter='all',workspaceFiles={},scanToken=0;
function notify(message,error=false){$('#notice').textContent=message;$('#notice').className=error?'error':'';}
function render(){if(!report)return;const r=report;$('#header-file').textContent=r.filename;$('#aside-count').textContent=r.findings.length;$('#editor-meta').textContent=$('#source').value.split('\n').length+' LINES';$('#coverage').textContent=r.coverage==='partial'?'PARTIAL COVERAGE':'SUPPORTED SUBSET';$('#coverage').className='pill '+(r.coverage==='partial'?'partial':'');$('#summary').innerHTML=[['error',r.counts.error,'errors','Structure & conflicts'],['warning',r.counts.warning,'warnings','Review before building'],['',r.entries.length,'image entries','Explicit declarations'],['',r.commands.length,'startup commands',r.architecture]].map(([cls,n,label,sub])=>`<div class="metric ${cls}"><strong>${n}</strong><div><b>${label}</b><small>${esc(sub)}</small></div></div>`).join('');renderFindings();renderStartup();renderManifest();renderComparison();}
function finding(f,i,mode=''){return `<article class="finding"><div class="finding-top"><span class="severity ${f.level}">${f.level}</span><span>${f.code}${mode?' · '+mode:''}</span><button class="source-location" data-finding="${i}" title="Select source line">${esc(f.file)}:${f.line} ↗</button></div><h3>${esc(f.message)}</h3><p>${esc(f.detail)}</p><p>${esc(f.help)}</p><a href="${f.url}" target="_blank" rel="noreferrer">QNX reference ↗</a></article>`;}
function renderFindings(){const rows=report.findings.map((f,i)=>({f,i})).filter(({f})=>filter==='all'||filter===f.level);$('#findings').innerHTML=rows.map(({f,i})=>finding(f,i)).join('')||`<div class="empty"><span class="circle">✓</span><strong>${report.findings.length?'Nothing in this filter.':'No findings in the supported subset.'}</strong>${report.findings.length?'Try another severity filter.':'Continue with mkifs and target boot testing.<br>This result does not certify a bootable image.'}</div>`;}
function renderStartup(){$('#startup').innerHTML=report.commands.map((c,i)=>`<div class="sequence-row"><span class="seq-num">${i+1}</span><div><code>${esc(c.raw)}</code><small>${esc(c.file)}:${c.line} · ${c.kind==='internal'?'QNX INTERNAL':c.resolved?'DECLARED '+esc(c.resolved):'NOT EXPLICITLY DECLARED'} · ${c.background?'BACKGROUND':'FOREGROUND'}</small></div></div>`).join('')||'<div class="empty">No inline [+script] commands inspected.</div>';}
function renderManifest(){if(!report)return;const q=$('#manifest-search').value.toLowerCase();$('#manifest').innerHTML=report.entries.filter(e=>[e.path,e.source,e.kind].join(' ').toLowerCase().includes(q)).map(e=>`<div class="entry"><code>${esc(e.path||e.target)}</code><small><span class="kind">${e.kind.toUpperCase()}</span>${esc(e.source??'inline content')}<br>${esc(e.file)}:${e.line}</small></div>`).join('')||'<div class="empty">No matching image entries.</div>';}
function renderComparison(){if(!baseline){$('#comparison').innerHTML='<div class="empty">No baseline yet.<br>Pin a scan, then load or edit another revision.</div>';return;}const diff=compare(baseline,report);$('#comparison').innerHTML=`<div class="diff-summary"><strong>${diff.resolved.length} resolved · ${diff.introduced.length} introduced · ${diff.unchanged.length} unchanged</strong><br>Baseline: ${esc(baseline.filename)} · ${baseline.findings.length} findings</div>`+diff.resolved.map(f=>`<div class="entry"><span class="kind">RESOLVED</span><code>${f.code} ${esc(f.message)}</code></div>`).join('')+diff.introduced.map(f=>`<div class="entry"><span class="kind">INTRODUCED</span><code>${f.code} ${esc(f.message)}</code></div>`).join('');}
function scan(){try{const filename=$('#filename').value.trim();if(!filename)throw Error('Give the root buildfile a path.');report=analyze($('#source').value,{filename,files:workspaceFiles});render();return true;}catch(e){notify(e.message,true);return false;}}
function tab(name){$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));['diagnostics','startup','manifest','compare'].forEach(n=>$('#'+n+'-pane').hidden=n!==name);$('#view-title').textContent={diagnostics:'Preflight findings',startup:'Startup sequence',manifest:'Image manifest',compare:'Compare revisions'}[name];}
$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderFindings();});$('#manifest-search').oninput=renderManifest;
$('#scan').onclick=()=>{scanToken++;if(scan())notify('Scan updated. Configuration text was analyzed locally; nothing was executed.');};$('#source').oninput=()=>{scanToken++;notify('Source changed. Run preflight to update the results.');};$('#filename').onchange=()=>{const next=$('#filename').value.trim();if(Object.hasOwn(workspaceFiles,next)){$('#source').value=workspaceFiles[next];scan();notify('Opened supplied root '+next+'.');}else notify('Diagnostic filename changed. Run preflight to update results.');};
async function fixture(name){const token=++scanToken;try{const response=await fetch(name+'.build');if(!response.ok)throw Error('Fixture could not be loaded.');const text=await response.text();if(token!==scanToken)return;$('#source').value=text;$('#filename').value='image.build';workspaceFiles={};scan();notify((name==='broken'?'Issue':'Reviewed')+' fixture loaded. Authored examples are not board-qualified QNX images.');}catch(e){notify(e.message,true)}}$('#broken').onclick=()=>fixture('broken');$('#reviewed').onclick=()=>fixture('reviewed');
$('#upload').onclick=()=>$('#files').click();$('#files').onchange=async e=>{try{const files=[...e.target.files];if(!files.length)return;scanToken++;if(files.length>100)throw Error('Open at most 100 buildfiles.');let total=0;const loaded={};for(const f of files){total+=f.size;if(f.size>2000000||total>10000000)throw Error('Limit: 2 MB per file and 10 MB total.');const name=f.webkitRelativePath||f.name;if(Object.hasOwn(loaded,name))throw Error('Duplicate filename: '+name);loaded[name]=await f.text();}const root=Object.keys(loaded).find(x=>/\.(build|bld)$/.test(x))||Object.keys(loaded)[0];workspaceFiles=loaded;$('#filename').value=root;$('#source').value=loaded[root];scan();notify(files.length+' local files opened. The first .build/.bld file is the root; set another supplied root path if needed.');}catch(e){notify(e.message,true)}finally{e.target.value=''}};
$('#findings').onclick=e=>{const b=e.target.closest('[data-finding]');if(!b)return;const f=report.findings[Number(b.dataset.finding)];if(f.file!==$('#filename').value.trim()){notify('Finding is in companion file '+f.file+':'+f.line+'. Open that file as the root to edit it.');return;}const lines=$('#source').value.split('\n'),start=lines.slice(0,f.line-1).join('\n').length+(f.line>1?1:0);$('#source').focus();$('#source').setSelectionRange(start,start+(lines[f.line-1]?.length||0));$('#source').scrollTop=Math.max(0,(f.line-5)*21);notify('Selected '+f.file+':'+f.line+'. Edit source and run preflight.');};
$('#pin').onclick=()=>{baseline=structuredClone(report);renderComparison();notify('Current scan pinned as baseline. Load the reviewed fixture or edit the source to compare.');};
function download(format){if(!scan())return;const value=format==='sarif'?sarif(report):report;const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bootlens.'+(format==='sarif'?'sarif':'json');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(format.toUpperCase()+' report exported from a fresh scan.');}$('#json').onclick=()=>download('json');$('#sarif').onclick=()=>download('sarif');
fixture('broken');
